package com.srent.room;
import org.springframework.data.web.PageableDefault;
import com.srent.audit.AuditService; import com.srent.common.ApiException; import com.srent.property.*; import com.srent.security.CurrentUser; import jakarta.persistence.criteria.JoinType; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.data.jpa.domain.Specification; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.util.*;
@RestController @RequestMapping("/api/v1/rooms") @RequiredArgsConstructor
public class RoomController {
    private final RoomRepository rooms; private final PropertyRepository properties; private final AuditService audit;
    public record Request(@NotNull UUID propertyId,@NotBlank @Size(max=180) String title,@Size(max=5000) String description,@NotNull @DecimalMin("0") BigDecimal monthlyPrice,@NotNull @DecimalMin("1") BigDecimal areaSqm,@Size(max=2000) Set<String> amenities,@Min(1) @Max(20) int maxOccupants,Room.Status status){}
    public record Response(UUID id,UUID propertyId,String propertyName,String address,String district,String city,BigDecimal latitude,BigDecimal longitude,String title,String description,BigDecimal monthlyPrice,BigDecimal areaSqm,Set<String> amenities,int maxOccupants,Room.Status status,Room.ApprovalStatus approvalStatus,String rejectionReason){public static Response from(Room r){var p=r.getProperty();return new Response(r.getId(),p.getId(),p.getName(),p.getAddressLine(),p.getDistrict(),p.getCity(),p.getLatitude(),p.getLongitude(),r.getTitle(),r.getDescription(),r.getMonthlyPrice(),r.getAreaSqm(),split(r.getAmenities()),r.getMaxOccupants(),r.getStatus(),r.getApprovalStatus(),r.getRejectionReason());}}
    @PostMapping @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasRole('LANDLORD')") @Transactional public Response create(@Valid @RequestBody Request q){var p=ownedProperty(q.propertyId());var r=new Room();r.setProperty(p);map(r,q);return Response.from(rooms.save(r));}
    @PutMapping("/{id}") @PreAuthorize("hasRole('LANDLORD')") @Transactional public Response update(@PathVariable UUID id,@Valid @RequestBody Request q){var r=owned(id);if(r.getApprovalStatus()==Room.ApprovalStatus.PENDING)throw ApiException.conflict("ROOM_PENDING_REVIEW","Không thể sửa phòng đang chờ duyệt");var p=ownedProperty(q.propertyId());r.setProperty(p);map(r,q);r.setApprovalStatus(Room.ApprovalStatus.DRAFT);r.setRejectionReason(null);return Response.from(r);}
    @GetMapping public Page<Response> search(@RequestParam(required=false) String city,@RequestParam(required=false) String district,@RequestParam(required=false) BigDecimal minPrice,@RequestParam(required=false) BigDecimal maxPrice,@RequestParam(required=false) BigDecimal minArea,@RequestParam(required=false) String amenity,@PageableDefault(size=20,sort="createdAt",direction=Sort.Direction.DESC) Pageable page){
        Specification<Room> s=(root,q,cb)->{root.fetch("property",JoinType.INNER);q.distinct(true);return cb.and(cb.equal(root.get("approvalStatus"),Room.ApprovalStatus.APPROVED),cb.notEqual(root.get("status"),Room.Status.HIDDEN));};
        if(city!=null)s=s.and((r,q,c)->c.equal(c.lower(r.get("property").get("city")),city.toLowerCase())); if(district!=null)s=s.and((r,q,c)->c.equal(c.lower(r.get("property").get("district")),district.toLowerCase())); if(minPrice!=null)s=s.and((r,q,c)->c.greaterThanOrEqualTo(r.get("monthlyPrice"),minPrice));if(maxPrice!=null)s=s.and((r,q,c)->c.lessThanOrEqualTo(r.get("monthlyPrice"),maxPrice));if(minArea!=null)s=s.and((r,q,c)->c.greaterThanOrEqualTo(r.get("areaSqm"),minArea));if(amenity!=null)s=s.and((r,q,c)->c.like(c.lower(r.get("amenities")),"%"+amenity.toLowerCase()+"%"));return rooms.findAll(s,page).map(Response::from);}
    @GetMapping("/{id}") @Transactional(readOnly=true) public Response one(@PathVariable UUID id){var r=rooms.findById(id).orElseThrow(()->ApiException.notFound("Phòng"));if(r.getApprovalStatus()!=Room.ApprovalStatus.APPROVED&&!isOwner(r)&&CurrentUser.principal().role()!=com.srent.user.User.Role.ADMIN)throw ApiException.notFound("Phòng");return Response.from(r);}
    @GetMapping("/my") @PreAuthorize("hasRole('LANDLORD')") public Page<Response> mine(@PageableDefault(size=20,sort="createdAt",direction=Sort.Direction.DESC) Pageable p){return rooms.findAllByPropertyOwnerId(CurrentUser.id(),p).map(Response::from);}
    @PostMapping("/{id}/submit") @PreAuthorize("hasRole('LANDLORD')") @Transactional public Response submit(@PathVariable UUID id){var r=owned(id);if(r.getApprovalStatus()!=Room.ApprovalStatus.DRAFT&&r.getApprovalStatus()!=Room.ApprovalStatus.REJECTED)throw ApiException.conflict("INVALID_ROOM_STATE","Chỉ bài nháp hoặc bị từ chối mới có thể gửi duyệt");r.setApprovalStatus(Room.ApprovalStatus.PENDING);r.setRejectionReason(null);audit.log(CurrentUser.id(),"ROOM_SUBMITTED","ROOM",r.getId(),null);return Response.from(r);}
    private Room owned(UUID id){var r=rooms.findById(id).orElseThrow(()->ApiException.notFound("Phòng"));if(!isOwner(r))throw ApiException.forbidden("Bạn không sở hữu phòng này");return r;} private boolean isOwner(Room r){return r.getProperty().getOwner().getId().equals(CurrentUser.id());}
    private Property ownedProperty(UUID id){var p=properties.findById(id).orElseThrow(()->ApiException.notFound("Khu trọ"));if(!p.getOwner().getId().equals(CurrentUser.id()))throw ApiException.forbidden("Bạn không sở hữu khu trọ này");return p;}
    static void map(Room r,Request q){r.setTitle(q.title().trim());r.setDescription(q.description());r.setMonthlyPrice(q.monthlyPrice());r.setAreaSqm(q.areaSqm());r.setAmenities(q.amenities()==null?"":String.join(",",q.amenities()));r.setMaxOccupants(q.maxOccupants());r.setStatus(q.status()==null?Room.Status.AVAILABLE:q.status());}
    static Set<String> split(String s){return s==null||s.isBlank()?Set.of():new LinkedHashSet<>(Arrays.asList(s.split(",")));}
}
